package br.com.poolcontrol.financeiro.api;
import br.com.poolcontrol.financeiro.domain.*; import br.com.poolcontrol.financeiro.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/financeiro/caixas") @RequiredArgsConstructor public class CashController { private final CashRegisterRepository cash; private final CashMovementRepository movements; private final CashClosingRepository closings;
 @GetMapping List<CashRegister> list(){return cash.findAll();} @PostMapping CashRegister create(@RequestBody CashRegister c){return cash.save(c);} @GetMapping("/movimentacoes") List<CashMovement> movements(){return movements.findAll();} @PostMapping("/movimentacoes") CashMovement movement(@RequestBody CashMovement m){return movements.save(m);} @GetMapping("/fechamentos") List<CashClosing> closings(){return closings.findAll();} @PostMapping("/fechamentos") CashClosing closing(@RequestBody CashClosing c){return closings.save(c);} }
